-- Reescritura de las opciones múltiples de Ética: mismas preguntas, distractores más parejos en extensión y más finos,
-- y la respuesta correcta repartida de forma pareja entre a/b/c/d. Actualiza in place: no borra intentos ni respuestas.
-- Generado a partir de tools/casos_etica.json (mismo origen que seed_etica.sql). Se puede correr más de una vez.
begin;

update preguntas set texto = '¿Qué teoría ética expresa mejor el criterio adoptado por la dirección?', opciones = '{"a": "Contractualismo, porque la regla se apoya en un criterio objetivo que cualquier paciente aceptaría si conociera las probabilidades.", "b": "Utilitarismo, porque elige la asignación que maximiza el resultado agregado: más vidas salvadas con los recursos disponibles.", "c": "Deontología, porque trata a todos los pacientes con la misma regla y no hace excepciones según quién sea cada uno de ellos.", "d": "Ética de la virtud, porque la dirección actúa con prudencia al apoyarse en el mejor dato técnico disponible para decidir."}'::jsonb where id = 'etica-1-a';
update preguntas_clave set ok = 'b', porque = '{"a": "Contractualismo pide reglas justificables ante todos, incluido el peor ubicado; acá excluye sistemáticamente a los crónicos y nadie la acordó.", "c": "Aplicar una regla uniforme no es deontología: ésta mira deberes y dignidad con independencia del resultado, y acá el criterio es justamente el resultado.", "d": "La prudencia implica auditar el modelo; delegar sin revisar se parece más al vicio por exceso (credulidad ciega)."}'::jsonb where pregunta_id = 'etica-1-a';
update preguntas set texto = '¿Cuál es la objeción más fuerte contra ese criterio, según la clase 1?', opciones = '{"a": "Que ignora las consecuencias de las decisiones y se limita a aplicar reglas fijas, sin importar qué le pase a cada paciente.", "b": "Que exige conocer con certeza la probabilidad de supervivencia de cada paciente, algo que ningún modelo estadístico puede ofrecer.", "c": "Que reemplaza el juicio clínico por el de la dirección y, con eso, vulnera la autonomía profesional de la médica de guardia.", "d": "Que el cálculo agregado puede avalar perjudicar de forma sistemática a una minoría (los crónicos) si eso mejora el saldo global."}'::jsonb where id = 'etica-1-b';
update preguntas_clave set ok = 'd', porque = '{"a": "Eso describe una caricatura de la deontología; el utilitarismo, al revés, razona sólo con consecuencias.", "b": "El utilitarismo trabaja con expectativas y probabilidades; no requiere certeza, así que no es la objeción central.", "c": "La supervisión humana no es una preferencia personal; la objeción de fondo que marca la clase es distributiva, no la autonomía de la médica."}'::jsonb where pregunta_id = 'etica-1-b';
update preguntas set texto = 'Las familias piden discutir públicamente las reglas antes de la próxima ola. ¿Qué enfoque respalda ese pedido?', opciones = '{"a": "El contractualismo: una regla es legítima si puede justificarse ante todos los afectados, incluido quien queda peor ubicado.", "b": "El utilitarismo: discutir en público mejora la aceptación social de la regla y, con eso, el bienestar agregado del hospital.", "c": "La deontología: cada paciente debe ser tratado como fin en sí mismo, y eso se garantiza consultando previamente a las familias.", "d": "La ética de la virtud: un hospital virtuoso escucha a las familias, porque la deliberación conjunta forma el carácter institucional."}'::jsonb where id = 'etica-1-c';
update preguntas_clave set ok = 'a', porque = '{"b": "Podría mencionarse como efecto, pero el fundamento del pedido es la legitimidad de la regla, no su utilidad.", "c": "La deontología pide no tratar a nadie sólo como medio, pero no prescribe un procedimiento de consulta; lo que fundamenta el pedido es la justificabilidad de la regla.", "d": "La virtud mira el carácter del agente que decide, no la validación de las reglas ante los afectados."}'::jsonb where pregunta_id = 'etica-1-c';
update preguntas set texto = '¿Cómo se describe mejor la actitud de la médica que revisa cada caso?', opciones = '{"a": "Automation bias: deposita su confianza en el sistema, aunque luego lo corrige caso por caso según su experiencia clínica.", "b": "Deontología estricta: se niega a aceptar una regla que perjudique a algunos pacientes, sin considerar sus consecuencias globales.", "c": "Prudencia (justo medio): usa el modelo pero audita sus límites, evitando tanto rechazarlo por completo como aceptarlo a ciegas.", "d": "Vicio por defecto: rechaza el modelo por desconfianza general y decide por su cuenta, sin apoyarse en ningún dato del sistema."}'::jsonb where id = 'etica-1-d';
update preguntas_clave set ok = 'c', porque = '{"a": "El automation bias es sobreconfianza en la máquina; ella hace lo contrario: revisa lo que el sistema propone.", "b": "No rechaza el sistema ni ignora las consecuencias: exige revisarlo antes de aplicarlo.", "d": "Rechazar todo modelo sería el defecto; ella no lo descarta, lo somete a revisión caso por caso."}'::jsonb where pregunta_id = 'etica-1-d';
update preguntas set texto = '¿Qué fenómeno describe mejor por qué el contador envió el informe sin verificarlo?', opciones = '{"a": "Sesgo de confirmación: el contador buscó en el informe lo que ya creía sobre la situación fiscal del cliente ante el banco.", "b": "Sesgo de omisión: el asistente calló información relevante del cliente y el contador completó ese hueco por su propia cuenta.", "c": "Sesgo de autoridad tecnológica: una respuesta fluida y segura parece objetiva y se acepta sin contrastarla con otra fuente.", "d": "Concept drift: la situación fiscal del cliente cambió luego del entrenamiento y el modelo quedó desactualizado respecto de él."}'::jsonb where id = 'etica-2-a';
update preguntas_clave set ok = 'c', porque = '{"a": "Nada indica que el contador tuviera una creencia previa; el problema es la confianza en la herramienta.", "b": "La omisión sería no responder; el sistema respondió e inventó un dato.", "d": "El drift es un deterioro predictivo por cambios en los datos; acá hay una alucinación, un dato inventado."}'::jsonb where pregunta_id = 'etica-2-a';
update preguntas set texto = 'El proveedor invoca sus advertencias. ¿Qué crítica de la cátedra al caso Walters aplica mejor?', opciones = '{"a": "Que los disclaimers no bastan: el lenguaje del asistente induce confianza, y omitir controles puede generar responsabilidad sin dolo.", "b": "Que la responsabilidad recae en el proveedor, porque el usuario profesional confió razonablemente en una herramienta comercial.", "c": "Que los disclaimers son válidos si están redactados con claridad, porque el usuario acepta el riesgo al aceptar los términos.", "d": "Que no hay responsabilidad sin dolo, y como el error fue una alucinación y no una intención, no corresponde atribuirlo a nadie."}'::jsonb where id = 'etica-2-b';
update preguntas_clave set ok = 'a', porque = '{"b": "La clase también marca el deber del usuario profesional de verificar; no hay un único responsable.", "c": "La crítica apunta justamente a que ese consentimiento es irreal: nadie lee ni pondera esas advertencias.", "d": "Puede haber responsabilidad por diseño o por negligencia aun sin intención; es la crítica central al fallo."}'::jsonb where pregunta_id = 'etica-2-b';
update preguntas set texto = 'Sobre la información que los empleados pegaron en el chat, ¿cuál es el análisis correcto?', opciones = '{"a": "Los términos del proveedor cubren el tratamiento, ya que quien los acepta responde por los datos que carga en la herramienta.", "b": "Si el prompt sólo se usa para resumir y la salida no se conserva, no hay tratamiento de datos personales relevante.", "c": "Borrar la conversación después de obtener el resumen elimina el riesgo, porque la supresión de la cuenta destruye los datos.", "d": "El consentimiento de quien aceptó los términos no reemplaza la base jurídica para datos de terceros, y la salud es dato sensible."}'::jsonb where id = 'etica-2-c';
update preguntas_clave set ok = 'd', porque = '{"a": "Es lo que la clase niega: aceptar términos no legitima el tratamiento de datos de terceros.", "b": "Resumir implica recoger, consultar y combinar datos: es tratamiento.", "c": "In re OpenAI: ocultar de la cuenta no es eliminar ni destruir; puede haber órdenes de conservación."}'::jsonb where pregunta_id = 'etica-2-c';
update preguntas set texto = '¿Qué medida refleja mejor el principio de necesidad contextual?', opciones = '{"a": "Reemplazar los nombres por iniciales y conservar CUIT y balances completos, para que el resumen resulte lo más preciso posible.", "b": "Estructurar los prompts con categorías y roles en lugar de nombres, y reinsertar las identidades recién en el análisis local.", "c": "Enviar el contexto completo por un canal cifrado de extremo a extremo, ya que lo que hay que proteger es la transmisión.", "d": "Sumar más contexto a cada prompt para reducir las alucinaciones, y pedir al proveedor el compromiso de no reutilizar los datos."}'::jsonb where id = 'etica-2-d';
update preguntas_clave set ok = 'b', porque = '{"a": "Las iniciales y el CUIT siguen identificando a las personas; no hay minimización de lo expuesto.", "c": "Cifrar el canal no reduce lo que se expone al proveedor; la necesidad contextual pide enviar sólo lo necesario.", "d": "Es la lógica de maximización que choca con la minimización, y no elimina las alucinaciones."}'::jsonb where pregunta_id = 'etica-2-d';
update preguntas set texto = '¿Por qué quitar sexo, edad y nacionalidad no vuelve «ciego» al modelo?', opciones = '{"a": "Porque los atributos sensibles siguen presentes en los registros de entrenamiento y el modelo los usa aunque no figuren como columnas.", "b": "Porque un modelo sin atributos protegidos no puede medirse por grupo, y sin esa medición no se puede afirmar que sea justo.", "c": "Porque quitarlos reduce la accuracy y el modelo compensa sobreajustando al historial de pago de los grupos más numerosos.", "d": "Porque variables como código postal o recargas en efectivo pueden actuar como proxies de nivel socioeconómico y reconstruir el sesgo."}'::jsonb where id = 'etica-3-a';
update preguntas_clave set ok = 'd', porque = '{"a": "Al quitarlos, la columna desaparece; el problema son las otras variables que correlacionan con esas características.", "b": "Se puede medir por grupo con datos desagregados (lo hizo la ONG); el problema es que otras variables codifican el atributo.", "c": "No es un problema de accuracy ni de sobreajuste, sino de variables que funcionan como proxies."}'::jsonb where pregunta_id = 'etica-3-a';
update preguntas set texto = 'Con los datos de la ONG, ¿qué métrica de fairness se incumple claramente?', opciones = '{"a": "Predictive parity: la proporción de aprobados que terminan pagando difiere entre barrios, como se ve en los porcentajes informados.", "b": "Equal opportunity: entre quienes efectivamente pagaron, el modelo aprueba al 88 % de un grupo y sólo al 61 % del otro.", "c": "Demographic parity: la tasa total de aprobación difiere entre barrios, y eso surge de forma directa de las cifras de la ONG.", "d": "Ninguna se incumple: entre quienes no pagaron la aprobación es casi igual (9 % y 7 %), lo que muestra un trato equivalente."}'::jsonb where id = 'etica-3-b';
update preguntas_clave set ok = 'b', porque = '{"a": "Los porcentajes de la ONG están condicionados a quienes pagaron o no, no a quienes fueron aprobados; no permiten calcular predictive parity.", "c": "Las cifras no son tasas totales de aprobación: están condicionadas al comportamiento real de pago.", "d": "Un FPR parecido no alcanza; la diferencia en la tasa de verdaderos positivos (88 vs 61) ya es una violación."}'::jsonb where pregunta_id = 'etica-3-b';
update preguntas set texto = 'La empresa dice que el modelo «sólo refleja el comportamiento histórico». ¿Cuál es la mejor respuesta?', opciones = '{"a": "Es válido si los datos son reales y fueron bien cargados: un sistema entrenado con hechos verdaderos no puede resultar injusto.", "b": "Es válido si la empresa publica el código y las variables usadas, porque la transparencia alcanza para descartar discriminación.", "c": "Reflejar desigualdades históricas con precisión es sesgo sistémico: reproducirlas no es neutralidad, es perpetuarlas.", "d": "Es parcialmente válido: la empresa responde por el sesgo que ella introduzca, no por el que ya existía en los datos de origen."}'::jsonb where id = 'etica-3-c';
update preguntas_clave set ok = 'c', porque = '{"a": "Datos verdaderos pueden codificar desigualdad; un sistema técnicamente impecable puede ser éticamente problemático.", "b": "Publicar el código no corrige el sesgo ni equivale a explicarlo.", "d": "La cátedra no admite esa división: quien despliega el sistema responde por sus efectos, incluido el sesgo sistémico."}'::jsonb where pregunta_id = 'etica-3-c';
update preguntas set texto = '¿Qué medida de data governance y fairness corresponde recomendar primero?', opciones = '{"a": "Evaluar los resultados desagregados por grupo, revisar los proxies y definir con los afectados qué métrica de fairness se adopta.", "b": "Volver a incluir sexo, edad y nacionalidad para ganar precisión global, ya que el modelo actual pierde información relevante.", "c": "Subir el umbral de aprobación para toda la cartera y así reducir la mora total sin modificar las variables del modelo.", "d": "Reemplazarlo por un modelo más complejo que capture mejor los patrones y reduzca el error en los barrios populares."}'::jsonb where id = 'etica-3-d';
update preguntas_clave set ok = 'a', porque = '{"b": "Mejorar accuracy con categorías protegidas es exactamente el dilema de Loomis, no una solución.", "c": "Cambia la distribución de errores sin mirar a los grupos; puede empeorar la brecha.", "d": "Más complejidad suele restar explicabilidad y no ataca el sesgo que traen los datos."}'::jsonb where pregunta_id = 'etica-3-d';
update preguntas set texto = '¿Qué tipo de drift describe mejor que la asistencia presencial ya no indique compromiso?', opciones = '{"a": "Concept drift: cambió la relación entre la asistencia presencial y lo que se quiere predecir, aunque los datos sigan llegando igual.", "b": "Data drift: cambió la distribución de los inputs, por lo que el modelo recibe valores fuera del rango con el que fue entrenado.", "c": "Model drift por cambio de código: el proveedor actualizó el sistema en 2026 y el nuevo algoritmo pondera distinto la asistencia.", "d": "Sesgo de medición: la asistencia siempre fue una mala variable, y la caída de precisión recién la hizo visible en 2026."}'::jsonb where id = 'etica-4-a';
update preguntas_clave set ok = 'a', porque = '{"b": "Ese sería un cambio de distribución; acá el punto central es que la variable perdió significado, no que salga de rango.", "c": "El model drift no requiere cambios de código; nada indica que el proveedor modificara el sistema.", "d": "Predijo bien (88 %) hasta que cambió el contexto; no siempre fue mala, dejó de serlo."}'::jsonb where pregunta_id = 'etica-4-a';
update preguntas set texto = '¿Qué riesgo ético concreto genera, para los estudiantes marcados en rojo, la forma en que los tutores usan la clasificación?', opciones = '{"a": "Discriminación directa: la regla del sistema usa una categoría protegida para decidir quién recibe menos horas de tutoría.", "b": "Sesgo de confirmación: los tutores buscan pruebas de que los verdes rinden más y descuidan los datos que contradicen al modelo.", "c": "Profecía autocumplida: si los rojos reciben menos apoyo, puede producirse el abandono que el sistema decía anticipar.", "d": "Un problema técnico de calibración: el umbral entre amarillo y rojo está mal ajustado y se corrige reentrenando el modelo."}'::jsonb where id = 'etica-4-b';
update preguntas_clave set ok = 'c', porque = '{"a": "No hay una categoría protegida escrita en la regla del sistema.", "b": "Describe un vicio cognitivo de los tutores; el riesgo para los rojos es que la clasificación contribuye a producir el resultado.", "d": "Reentrenar no corrige que la clasificación se use para dar menos apoyo a quien más lo necesita."}'::jsonb where pregunta_id = 'etica-4-b';
update preguntas set texto = '¿Qué pregunta de ALTAI debió hacerse antes del despliegue para evitar ese efecto?', opciones = '{"a": "¿El proveedor documentó la arquitectura del modelo y las métricas de precisión obtenidas durante la validación inicial?", "b": "¿La clasificación ayuda al estudiante a identificar necesidades, o puede estigmatizarlo y reducir sus oportunidades?", "c": "¿Los datos de asistencia y de uso del campus virtual se almacenan cifrados y con acceso restringido al personal autorizado?", "d": "¿El sistema se probó en un piloto antes del despliegue y su precisión inicial superó el umbral fijado por la universidad?"}'::jsonb where id = 'etica-4-c';
update preguntas_clave set ok = 'b', porque = '{"a": "La documentación técnica y la precisión no dicen nada sobre el efecto de la clasificación en el alumno.", "c": "Es una pregunta de seguridad de datos, válida pero distinta: no evita el efecto del uso de la clasificación.", "d": "Mide desempeño técnico, no el impacto sobre el bienestar y las oportunidades de cada estudiante."}'::jsonb where pregunta_id = 'etica-4-c';
update preguntas set texto = 'Área académica, proveedor y tutores se señalan entre sí. ¿Cómo se califica y cómo se resuelve?', opciones = '{"a": "Es responsabilidad compartida: cada actor cubre su tramo, y alcanza con que el contrato distribuya los riesgos entre las partes.", "b": "Es responsabilidad del proveedor: construyó y entrenó el sistema, así que responde por el uso que hace de él la universidad.", "c": "Es responsabilidad de los tutores: son quienes aplican la clasificación al alumno, por lo que responden por sus efectos.", "d": "Es responsabilidad diluida: corresponde fijar de antemano obligaciones concretas, con decisiones reconstruibles y alguien que responda."}'::jsonb where id = 'etica-4-d';
update preguntas_clave set ok = 'd', porque = '{"a": "Cuando cada uno dice «sólo hice mi parte» y nadie responde, es responsabilidad diluida, no compartida.", "b": "Las decisiones de uso y de contrato son de la universidad; culpar a un solo eslabón no resuelve el problema.", "c": "Culpar sólo al eslabón final repite el patrón del caso Uber; el diseño y el contrato dependen de otros."}'::jsonb where pregunta_id = 'etica-4-d';
update preguntas set texto = '¿Cómo clasificaría el AI Act el producto (1), inferencia de emociones de los operadores?', opciones = '{"a": "Alto riesgo: al afectar el empleo exige documentación, supervisión humana efectiva y evaluación de conformidad antes de usarse.", "b": "Práctica prohibida como regla: inferir emociones de los trabajadores en su lugar de trabajo está vedado, salvo excepciones acotadas.", "c": "Riesgo de transparencia: alcanza con avisar a los operadores que se analizan sus emociones y obtener su conformidad.", "d": "Riesgo mínimo: analiza voz y rostro con fines de bienestar y no toma decisiones formales sobre los operadores."}'::jsonb where id = 'etica-5-a';
update preguntas_clave set ok = 'b', porque = '{"a": "El empleo es un área de alto riesgo, pero esta práctica específica sube un escalón: es prohibida.", "c": "Informar no alcanza cuando la práctica está prohibida.", "d": "Inferir emociones de empleados no es riesgo mínimo; está en la lista de prohibiciones."}'::jsonb where pregunta_id = 'etica-5-a';
update preguntas set texto = 'El chatbot «Lucía» (producto 2) no aclara que es IA. ¿Cuál es el encuadre correcto?', opciones = '{"a": "Riesgo de transparencia: el problema no es el chatbot en sí, sino que la persona no sepa que está interactuando con una máquina.", "b": "Práctica prohibida por manipulación: el nombre humano busca generar confianza indebida y altera la decisión del cliente.", "c": "Alto riesgo: la atención al cliente de una empresa con clientes en la UE requiere evaluación de conformidad y registro.", "d": "Riesgo mínimo: los chatbots comerciales quedan fuera de las obligaciones del reglamento mientras no traten datos sensibles."}'::jsonb where id = 'etica-5-b';
update preguntas_clave set ok = 'a', porque = '{"b": "Un nombre humano no es por sí una técnica subliminal perjudicial; el encuadre de la cátedra es transparencia.", "c": "La atención comercial básica no está entre las áreas de alto riesgo mencionadas.", "d": "Los chatbots sí tienen obligación de transparencia, traten o no datos sensibles."}'::jsonb where pregunta_id = 'etica-5-b';
update preguntas set texto = 'Respecto del filtro de CV (producto 3), ¿qué rol tiene cada empresa?', opciones = '{"a": "Ambos son providers, porque el banco lo incorporó a su proceso de selección y lo puso a funcionar con sus propios criterios.", "b": "El banco es provider porque decide para qué se usa el sistema, y la empresa cordobesa es deployer del software que le vendió.", "c": "La empresa cordobesa es provider, pero sólo ella responde: el banco es un usuario final sin obligaciones propias en el reglamento.", "d": "La empresa cordobesa es provider (lo desarrolla y comercializa); el banco es deployer (lo usa bajo su autoridad). Ambos tienen obligaciones."}'::jsonb where id = 'etica-5-c';
update preguntas_clave set ok = 'd', porque = '{"a": "Provider es quien desarrolla y pone en el mercado; el banco lo usa bajo su autoridad, que es el rol de deployer.", "b": "Invierte los roles.", "c": "El deployer también tiene obligaciones (por ejemplo, supervisión humana y uso conforme)."}'::jsonb where pregunta_id = 'etica-5-c';
update preguntas set texto = 'El banco dice que «hay supervisión humana porque RR.HH. elige entre los finalistas». ¿Qué respondés?', opciones = '{"a": "Alcanza: el reglamento pide que un humano conserve la decisión final de contratación, y RR.HH. la tiene sobre los finalistas.", "b": "Alcanza si RR.HH. ve el score asignado a cada finalista y puede modificar el orden antes de elegir a quién contratar.", "c": "No alcanza: si el filtro ya descartó al 85 %, la decisión material se tomó antes de que intervenga una persona en el proceso.", "d": "No alcanza, pero se resuelve con una revisión de una muestra de los CV descartados, hecha una vez por año."}'::jsonb where id = 'etica-5-d';
update preguntas_clave set ok = 'c', porque = '{"a": "El AI Act exige medidas efectivas, no meramente formales.", "b": "Ver el score de los finalistas no controla los descartes previos.", "d": "Una auditoría anual espaciada no es supervisión efectiva de decisiones que se toman de forma continua."}'::jsonb where pregunta_id = 'etica-5-d';
update preguntas set texto = 'Según la lógica del fallo GEMA c/ SUNO, ¿qué dato técnico es jurídicamente determinante?', opciones = '{"a": "La escala del dataset: cuantas más obras se usan en el entrenamiento, más probable es que el tribunal vea una infracción.", "b": "La arquitectura: los modelos difusivos no almacenan obras por cómo están diseñados, así que quedan fuera de la reproducción.", "c": "El grado de memorization: que las obras del dataset puedan reproducirse desde el modelo con prompts simples y sin mayor esfuerzo.", "d": "La jurisdicción de entrenamiento: la ley del país donde están los servidores define si hubo o no reproducción de obras."}'::jsonb where id = 'etica-6-a';
update preguntas_clave set ok = 'c', porque = '{"a": "El volumen no define la infracción; lo decisivo es si las obras reaparecen.", "b": "Es la defensa de «aprende patrones»; el tribunal la descartó cuando las obras eran reproducibles.", "d": "El tribunal no se apoyó en el lugar del servidor; miró si los outputs reproducían las obras."}'::jsonb where pregunta_id = 'etica-6-a';
update preguntas set texto = '¿Aplica la excepción de Text and Data Mining a las obras con reserva legible por máquina?', opciones = '{"a": "Sí: la excepción cubre cualquier entrenamiento con contenido público, y la reserva del titular sólo vale para uso directo de la obra.", "b": "Sí, siempre que no se comercialicen las imágenes generadas, porque la excepción está pensada para usos de investigación.", "c": "No, porque el TDM está pensado para textos y bases de datos, y no cubre imágenes ni música en ningún caso.", "d": "No: el titular puede reservar sus derechos en formato legible por máquina, y con esa reserva la excepción no alcanza al entrenamiento."}'::jsonb where id = 'etica-6-b';
update preguntas_clave set ok = 'd', porque = '{"a": "La excepción tiene condiciones; el opt-out del titular la excluye.", "b": "El material no condiciona la excepción a la gratuidad: lo que la excluye es la reserva del titular.", "c": "Se discutió justamente con música en GEMA c/ SUNO; el criterio no es el tipo de obra."}'::jsonb where pregunta_id = 'etica-6-b';
update preguntas set texto = 'PincelAI dice que el parecido lo causa el usuario con su prompt. ¿Qué respondería el razonamiento de Múnich?', opciones = '{"a": "Con prompts simples y con datos y arquitectura elegidos por la empresa, el resultado lo determina el modelo: responde la empresa.", "b": "El usuario interrumpe la cadena causal al pedir un estilo concreto, así que la responsabilidad recae únicamente en él.", "c": "Responden ambos por igual, porque el output surge de la combinación entre el pedido del usuario y el modelo entrenado.", "d": "La responsabilidad depende de que la empresa haya tenido intención de copiar; sin ese dolo, no hay infracción atribuible."}'::jsonb where id = 'etica-6-c';
update preguntas_clave set ok = 'a', porque = '{"b": "Es la defensa de SUNO que el tribunal rechazó.", "c": "El fallo no repartió en partes iguales; atribuyó los outputs a SUNO.", "d": "Los outputs que reproducen obras generan responsabilidad sin necesidad de probar intención."}'::jsonb where pregunta_id = 'etica-6-c';
update preguntas set texto = '¿Qué medida de ingeniería reduce mejor el riesgo jurídico y ético?', opciones = '{"a": "Publicar un aviso de que las imágenes pueden parecerse a obras existentes y trasladar al usuario el chequeo de originalidad.", "b": "Registrar la procedencia de los datos respetando los opt-outs, testear memorization y filtrar outputs muy similares a obras existentes.", "c": "Trasladar el entrenamiento a una jurisdicción con excepciones de copyright más amplias y documentar esa decisión con cuidado.", "d": "Bajar la resolución de las imágenes generadas y agregar variaciones aleatorias para diferenciarlas de las portadas originales."}'::jsonb where id = 'etica-6-d';
update preguntas_clave set ok = 'b', porque = '{"a": "Un disclaimer no elimina la reproducción ni la responsabilidad.", "c": "Es arbitraje regulatorio; no corrige que los outputs reproduzcan obras.", "d": "Esconde el síntoma sin resolver la memorization."}'::jsonb where pregunta_id = 'etica-6-d';
update preguntas set texto = '¿Por qué «no alcanzó el puntaje» no es una explicación suficiente?', opciones = '{"a": "Porque una explicación válida debe incluir el código fuente y los coeficientes exactos para poder reproducir el puntaje.", "b": "Porque la respuesta debía venir de la empresa proveedora, que es la única que conoce el funcionamiento interno del sistema.", "c": "Porque el municipio no le informó cuál fue el puntaje de corte ni la posición que ocupó Mariela en el ranking.", "d": "Porque no dice qué datos se usaron ni qué factores pesaron, qué habría cambiado el resultado, ni cómo se puede impugnar."}'::jsonb where id = 'etica-7-a';
update preguntas_clave set ok = 'd', porque = '{"a": "Transparencia no es publicar todo: la persona necesita una explicación comprensible, no miles de líneas.", "b": "Quien decide sobre la persona es quien debe responder; no puede delegar la explicación.", "c": "Saber el puntaje o la posición es información, no explicación: no dice qué factores pesaron ni cómo cuestionar."}'::jsonb where pregunta_id = 'etica-7-a';
update preguntas set texto = 'Frente al secreto comercial invocado por la empresa, ¿qué criterio surge del material?', opciones = '{"a": "El secreto comercial prevalece sobre la explicación cuando el sistema lo compró un organismo público a un privado con contrato vigente.", "b": "El secreto cede en cuanto un ciudadano pide la explicación, ya que el interés del afectado desplaza al interés comercial.", "c": "El secreto comercial no extingue el derecho a la explicación: puede darse acceso reservado a un tribunal o auditor y ponderar.", "d": "El secreto sólo cede si la familia prueba antes que el sistema discriminó, y recién entonces se accede a su lógica."}'::jsonb where id = 'etica-7-b';
update preguntas_clave set ok = 'c', porque = '{"a": "El uso público del software refuerza el deber de explicar (BOSCO); no lo anula.", "b": "Tampoco desaparece de forma automática: se pondera caso por caso.", "d": "Exigir prueba previa sin acceso a la lógica deja al afectado indefenso; es el problema que BOSCO resuelve."}'::jsonb where pregunta_id = 'etica-7-b';
update preguntas set texto = 'El argumento de que explicar permitiría «manipular» el sistema se parece a:', opciones = '{"a": "El argumento de Uber en Aslam: las familias, como los conductores, elegirían libremente cómo presentar sus datos al sistema.", "b": "La seguridad por oscuridad que el Supremo desarmó en BOSCO: un riesgo abstracto de vulneración no justifica la opacidad.", "c": "La defensa de los buscadores en Denegri: la información no debe alterarse porque afectaría la libertad de expresión de terceros.", "d": "La noción de drift: si las familias ajustan sus datos con el tiempo, el modelo pierde su relación con lo que predice."}'::jsonb where id = 'etica-7-c';
update preguntas_clave set ok = 'b', porque = '{"a": "Aslam trata sobre subordinación laboral, no sobre opacidad.", "c": "Denegri pondera privacidad y libertad de expresión, no el secreto de un algoritmo.", "d": "El drift es un cambio en los datos del mundo, no una estrategia para sostener la opacidad."}'::jsonb where pregunta_id = 'etica-7-c';
update preguntas set texto = 'En el derecho argentino, ¿qué norma se activa más directamente si el rechazo es un acto administrativo basado sólo en el puntaje?', opciones = '{"a": "El art. 20 de la Ley 25.326: un acto que valora conductas no puede fundarse sólo en un perfil informatizado (nulidad insanable).", "b": "El art. 43 de la Constitución: el hábeas data permite a Mariela exigir que se publique la lógica de todos los algoritmos estatales.", "c": "El art. 17 del GDPR: Mariela puede pedir la supresión de sus datos del sistema, con lo que el rechazo pierde su fundamento.", "d": "El art. 4.7 de la Ley 25.326: los datos deben conservarse sólo por el tiempo necesario, por lo que el puntaje no puede usarse luego."}'::jsonb where id = 'etica-7-d';
update preguntas_clave set ok = 'a', porque = '{"b": "El art. 43 consagra el hábeas data (acceso a los datos propios), no la publicación de todos los algoritmos.", "c": "El GDPR no rige directamente acá, y la supresión no resuelve la falta de fundamento del acto.", "d": "Regula el plazo de conservación, no que el acto administrativo se apoye únicamente en un perfil automatizado."}'::jsonb where pregunta_id = 'etica-7-d';
update preguntas set texto = '¿Qué dato muestra el problema de fairness con más precisión?', opciones = '{"a": "La accuracy global del 93 %, porque un valor tan alto indica que el modelo acierta con la misma calidad en todas las edades.", "b": "Que entre pacientes que sí desarrollaron sepsis, el sistema alerta al 90 % de los menores de 60 pero sólo al 64 % de los mayores de 75.", "c": "Que el modelo se entrenó con datos de un hospital de otro país y con población mayormente joven, distinta de la local.", "d": "Que los enfermeros descartan el 80 % de las alertas, lo que muestra que el modelo genera demasiadas falsas alarmas en mayores."}'::jsonb where id = 'etica-8-a';
update preguntas_clave set ok = 'b', porque = '{"a": "Es precisamente el promedio que oculta el problema: accuracy no es fairness.", "c": "Es la causa probable (representación), no la medida que muestra la disparidad.", "d": "Muestra un problema de uso humano (fatiga) y no mide por sí mismo la disparidad entre grupos."}'::jsonb where pregunta_id = 'etica-8-a';
update preguntas set texto = 'En este sistema, ¿qué tipo de error tiene el costo más grave para el paciente?', opciones = '{"a": "Falso positivo: cada alerta innecesaria consume tiempo de enfermería y, acumuladas, desplazan la atención de los casos reales.", "b": "Ambos tienen un costo equivalente, porque un error en cualquier dirección obliga a repetir estudios y demora el diagnóstico.", "c": "Falso negativo: un paciente con sepsis que no recibe alerta puede quedar sin tratamiento a tiempo, con un daño difícil de revertir.", "d": "Ninguno resulta grave, porque cada alerta o su ausencia pasa por la revisión de enfermería antes de una decisión clínica."}'::jsonb where id = 'etica-8-b';
update preguntas_clave set ok = 'c', porque = '{"a": "Tiene costos (y la fatiga importa), pero recaen más sobre el sistema y no se comparan con una sepsis no tratada.", "b": "Los costos son asimétricos; por eso la accuracy global no alcanza para evaluar el sistema.", "d": "Si descartan el 80 % sin revisar, la supervisión humana no protege al paciente."}'::jsonb where pregunta_id = 'etica-8-b';
update preguntas set texto = '¿Qué precedente apoya exigir validar el modelo en la población a la que se aplica?', opciones = '{"a": "State v. Loomis: el tribunal exigió validar cualquier algoritmo en cada población antes de usarlo en decisiones sobre personas.", "b": "GEMA c/ SUNO: el tribunal exigió validar los modelos con datos de la población local para evitar reproducir obras.", "c": "Costeja: el TJUE ordenó verificar que los datos usados por un servicio sigan siendo exactos y pertinentes para la población afectada.", "d": "Ewert v. Canada: instrumentos validados con una población se aplicaron a otra, y se cuestionó que aseguraran la exactitud debida."}'::jsonb where id = 'etica-8-c';
update preguntas_clave set ok = 'd', porque = '{"a": "Loomis no impuso esa exigencia; admitió el uso del algoritmo con límites y advertencias.", "b": "GEMA trata de copyright y memorization, no de validación poblacional.", "c": "Costeja trata de desindexación en buscadores, no de validar modelos."}'::jsonb where pregunta_id = 'etica-8-c';
update preguntas set texto = 'Sobre las alertas descartadas y la negativa a mover el threshold, ¿qué análisis es el más completo?', opciones = '{"a": "La supervisión se volvió formal por la fatiga de alertas, y el umbral es una decisión ética que requiere validarse por subgrupo.", "b": "Bajar el umbral para todos resuelve la brecha, porque en salud un falso negativo pesa más que cualquier costo operativo.", "c": "El umbral es una decisión técnica del proveedor, y al hospital le corresponde sólo capacitar a los enfermeros para revisar más alertas.", "d": "Los enfermeros son los responsables, porque descartan alertas sin revisarlas y así anulan la supervisión humana que el sistema prevé."}'::jsonb where id = 'etica-8-d';
update preguntas_clave set ok = 'a', porque = '{"b": "Ignora el costo de la fatiga, que ya vacía la supervisión, y no valida el efecto por grupo.", "c": "La cátedra insiste en que el umbral no es sólo técnico: implica elegir qué error tolerar y sobre quién recae.", "d": "Culpa al eslabón final sin mirar el diseño que genera 40 alertas por turno."}'::jsonb where pregunta_id = 'etica-8-d';
update preguntas set texto = '¿Qué concepto de la clase 5 describe lo que hace el algoritmo de RapiYa?', opciones = '{"a": "Automation: la plataforma sustituye tareas que antes hacían personas, y por eso los repartidores pierden su lugar de trabajo.", "b": "Augmentation: el algoritmo potencia la tarea del repartidor con mejores pedidos y rutas, y él conserva el control del trabajo.", "c": "Gestión algorítmica: el software asigna tareas, fija pagos, evalúa y sanciona, aunque el trabajador sigue haciendo el trabajo.", "d": "Exposure: las tareas de reparto son técnicamente automatizables, y el algoritmo es una etapa previa de esa sustitución."}'::jsonb where id = 'etica-9-a';
update preguntas_clave set ok = 'c', porque = '{"a": "Nicolás sigue haciendo el trabajo; no hay sustitución.", "b": "No se trata de ayudar a la tarea sino de dirigir y sancionar al trabajador.", "d": "La exposición a la automatización no es lo que describe el caso: hoy el algoritmo dirige, no reemplaza."}'::jsonb where pregunta_id = 'etica-9-a';
update preguntas set texto = '¿Qué criterio usaron Uber v. Aslam y Glovo para calificar la relación?', opciones = '{"a": "Lo que firmaron las partes prevalece, salvo que el trabajador pruebe un vicio del consentimiento al aceptar la categoría.", "b": "La realidad del control y la dependencia prevalece sobre la etiqueta contractual que la empresa eligió para la relación.", "c": "La titularidad de las herramientas: quien usa su propio vehículo y su celular es autónomo, aunque la app organice su actividad.", "d": "La exclusividad: sólo es trabajador quien presta servicios a una única plataforma y no puede conectarse a otras."}'::jsonb where id = 'etica-9-b';
update preguntas_clave set ok = 'b', porque = '{"a": "Los tribunales justamente penetraron la forma contractual para mirar la realidad.", "c": "No es el criterio del material: pesó la organización algorítmica del trabajo, no de quién eran las herramientas.", "d": "No es el criterio del material; lo que contó fue el control y la dependencia."}'::jsonb where pregunta_id = 'etica-9-b';
update preguntas set texto = '«Los socios eligen cuándo conectarse.» ¿Cuál es la respuesta de la clase?', opciones = '{"a": "Es la paradoja de la flexibilidad: si rechazar baja el puntaje y el puntaje define pedidos y continuidad, la libertad es formal.", "b": "Es una prueba de autonomía real: quien decide cuándo conectarse no está subordinado, aunque el algoritmo lo evalúe.", "c": "Sólo sería relevante si RapiYa exigiera por contrato un mínimo de horas semanales, porque la subordinación requiere una obligación expresa.", "d": "Es irrelevante para el derecho laboral, porque las plataformas digitales intermedian entre partes y no emplean a nadie."}'::jsonb where id = 'etica-9-c';
update preguntas_clave set ok = 'a', porque = '{"b": "Los tribunales vieron que la autonomía era muy limitada pese a la libertad horaria.", "c": "No hace falta una obligación expresa: el control opera a través del puntaje.", "d": "Uber y Glovo muestran lo contrario: se verificó dependencia."}'::jsonb where pregunta_id = 'etica-9-c';
update preguntas set texto = 'Nicolás fue desconectado por calificaciones en días de lluvia y no puede reclamar. ¿Qué principio falla más directamente?', opciones = '{"a": "Sostenibilidad: las entregas bajo lluvia aumentan el gasto energético de la plataforma y agravan su huella ambiental.", "b": "Propiedad intelectual: el algoritmo de puntaje es un activo protegido y por eso Nicolás no puede acceder a su lógica.", "c": "Alfabetización en IA: Nicolás no comprende cómo se calculan los puntajes, por lo que no pudo prevenir su desconexión.", "d": "Contestabilidad y accountability: hay una sanción automática sin explicación ni instancia de revisión humana donde impugnarla."}'::jsonb where id = 'etica-9-d';
update preguntas_clave set ok = 'd', porque = '{"a": "No es el problema central del caso.", "b": "La PI puede invocarse contra la transparencia, pero no es el principio que el caso vulnera.", "c": "Aun entendiendo el modelo, seguiría sin poder impugnar la sanción."}'::jsonb where pregunta_id = 'etica-9-d';
update preguntas set texto = '¿Por qué «todos tienen acceso al tutor» no garantiza igualdad de oportunidades?', opciones = '{"a": "Porque el acceso formal sólo iguala oportunidades si cada estudiante dispone de la misma cantidad de horas de uso del tutor.", "b": "Porque los modelos generativos grandes rinden peor en el español regional que en inglés, lo que penaliza a las escuelas rurales.", "c": "Porque el acceso gratuito crea una dependencia del proveedor que luego encarece el servicio para las escuelas con menos recursos.", "d": "Porque la brecha ya no es binaria: velocidad, dispositivo, habilidades y conectividad determinan quién puede beneficiarse de la IA."}'::jsonb where id = 'etica-10-a';
update preguntas_clave set ok = 'd', porque = '{"a": "Igualdad formal no es equidad: las mismas horas con peores condiciones no iguala.", "b": "Es un factor posible, pero no es lo que plantea el caso.", "c": "El costo futuro no es lo que plantea el caso; la brecha es la desigualdad en la capacidad efectiva de beneficiarse."}'::jsonb where pregunta_id = 'etica-10-a';
update preguntas set texto = 'Lo que advierten los docentes se describe mejor como:', opciones = '{"a": "Deskilling: al delegar sistemáticamente la tarea, los alumnos no desarrollan las capacidades para verificar lo que hace la IA.", "b": "Upskilling: los alumnos liberan tiempo de tareas rutinarias y pueden dedicarlo a aprender contenidos de mayor complejidad.", "c": "Augmentation: la IA amplía lo que el estudiante logra resolver, y él sigue siendo quien dirige y valida el resultado final.", "d": "Data drift: las respuestas del tutor se degradan con el tiempo y los alumnos no advierten que ya no son confiables."}'::jsonb where id = 'etica-10-b';
update preguntas_clave set ok = 'a', porque = '{"b": "El upskilling requiere formación y diseño; acá el tutor reemplaza el aprendizaje.", "c": "La augmentation supone que la persona sigue siendo central; acá entregan sin entender.", "d": "No hay un modelo predictivo que se deteriore: lo que se pierde son capacidades de los alumnos."}'::jsonb where pregunta_id = 'etica-10-b';
update preguntas set texto = 'Sobre el data center en zona de sequías, ¿qué análisis corresponde?', opciones = '{"a": "Es aceptable si el modelo consume menos por consulta que los anteriores, porque la eficiencia compensa el impacto de la ubicación.", "b": "Es irrelevante porque la nube es inmaterial y el consumo de agua atribuible a la IA es marginal frente al de otras industrias.", "c": "La ubicación es una decisión con consecuencias ambientales y sociales: el agua y la matriz eléctrica de la zona importan.", "d": "Sólo importa el consumo del entrenamiento inicial, porque las consultas posteriores del tutor tienen un costo energético despreciable."}'::jsonb where id = 'etica-10-c';
update preguntas_clave set ok = 'c', porque = '{"a": "Efecto rebote: más eficiencia por tarea puede aumentar el consumo total cuando el uso es masivo.", "b": "La clase dice lo contrario: la nube es infraestructura física y el estrés hídrico importa (UNEP).", "d": "A gran escala, la inferencia acumulada puede superar al entrenamiento."}'::jsonb where pregunta_id = 'etica-10-c';
update preguntas set texto = '¿Qué respuesta refleja mejor el enfoque de la clase frente a la política provincial?', opciones = '{"a": "Postergar todo uso de IA educativa hasta que se cierre por completo la brecha de conectividad en las escuelas rurales.", "b": "Evitar el determinismo: conectividad y formación primero, modelo adecuado al problema, diseño que evite deskilling y medición de impacto.", "c": "Implementar el programa tal como está, porque el acceso masivo a la tecnología produce por sí mismo mejores resultados educativos.", "d": "Elegir el modelo más grande disponible para garantizar la misma calidad de respuesta a todas las escuelas de la provincia."}'::jsonb where id = 'etica-10-d';
update preguntas_clave set ok = 'b', porque = '{"a": "Es la parálisis del vicio por defecto; la clase no propone prohibir.", "c": "Es determinismo tecnológico, justo lo que la clase pide evitar.", "d": "Green AI: no se trata de usar siempre el modelo más grande sino uno adecuado al problema."}'::jsonb where pregunta_id = 'etica-10-d';
update preguntas set texto = '¿El historial de compras permite legítimamente inferir enfermedades para ajustar precios?', opciones = '{"a": "No: la inferencia sigue siendo dato personal y acá sensible (salud); que el dato de origen sea lícito no legitima cualquier uso.", "b": "Sí: el cliente entregó sus compras voluntariamente, y la inferencia es un resultado del modelo, no un dato que él declaró.", "c": "Sí, mientras la empresa no revele las inferencias a terceros ajenos al grupo, porque el riesgo surge sólo al compartirlas.", "d": "No, pero sólo porque las inferencias del modelo pueden resultar estadísticamente incorrectas y perjudicar a algunos clientes."}'::jsonb where id = 'etica-11-a';
update preguntas_clave set ok = 'a', porque = '{"b": "Es el razonamiento que la clase rechaza expresamente.", "c": "El problema existe aunque no se comparta: el tratamiento mismo carece de base y de finalidad legítima.", "d": "Aun siendo correctas, el uso sería ilegítimo."}'::jsonb where pregunta_id = 'etica-11-a';
update preguntas set texto = 'La empresa dice que el cliente aceptó los términos. ¿Cuál es el análisis correcto?', opciones = '{"a": "Alcanza: aceptar los términos constituye consentimiento para los usos presentes y futuros que la empresa declare en ellos.", "b": "No hace falta consentimiento, porque la empresa tiene un interés legítimo en personalizar los precios y ofertas de sus clientes.", "c": "Sería inválido únicamente si el cliente fuera menor de edad o no tuviera capacidad para comprender los términos aceptados.", "d": "No alcanza: el consentimiento válido debe ser libre, específico, informado e inequívoco, y no cubre fines que no se informaron."}'::jsonb where id = 'etica-11-b';
update preguntas_clave set ok = 'd', porque = '{"a": "La cátedra pregunta justamente si páginas de términos generales son consentimiento informado.", "b": "El interés legítimo debe ponderarse con los derechos del titular; no habilita tratar datos de salud para cobrar más.", "c": "El vicio está en la falta de especificidad e información, no sólo en la capacidad del cliente."}'::jsonb where pregunta_id = 'etica-11-b';
update preguntas set texto = 'Guardar todo sin plazo «por si sirve» y vender un índice de salud a una aseguradora vulnera sobre todo:', opciones = '{"a": "Exactitud: al guardar datos sin plazo se vuelven obsoletos, y venderlos así transmite a la aseguradora información desactualizada.", "b": "Limitación de conservación y de finalidad (y minimización): no guardar más de lo necesario ni reutilizar los datos para otro fin.", "c": "Portabilidad: al vender el índice a un tercero, el cliente pierde la posibilidad de llevarse sus datos a otra cadena.", "d": "Derecho al olvido: los datos quedan disponibles indefinidamente y el cliente debería poder pedir su desindexación."}'::jsonb where id = 'etica-11-c';
update preguntas_clave set ok = 'b', porque = '{"a": "No es el problema principal descrito: el caso trata de cuánto se guarda y para qué se usa.", "c": "La portabilidad es un derecho del titular, no el principio vulnerado por la conservación y la venta.", "d": "No hay buscador ni desindexación en juego."}'::jsonb where pregunta_id = 'etica-11-c';
update preguntas set texto = 'Dar menos descuentos a quienes el modelo infiere en dificultades económicas plantea además:', opciones = '{"a": "Un problema legal: al corregir la base jurídica del tratamiento, desaparece también el cuestionamiento ético del precio diferencial.", "b": "Un problema de transparencia: se corrige avisando que los precios son personalizados, porque así el cliente decide si acepta.", "c": "Un problema de fairness: aun con tratamiento lícito, el resultado perjudica de manera sistemática a quienes están en peor situación.", "d": "Un problema de drift: la situación económica inferida deja de ser válida cuando cambia la del cliente y el modelo no se actualiza."}'::jsonb where id = 'etica-11-d';
update preguntas_clave set ok = 'c', porque = '{"a": "Legal no es lo mismo que ético: cumplir con datos no garantiza equidad.", "b": "Avisar no corrige el perjuicio distributivo.", "d": "El drift no es el núcleo; el problema existe desde el diseño."}'::jsonb where pregunta_id = 'etica-11-d';
update preguntas set texto = '¿Qué remedio piden, técnicamente, Ramiro y el exintendente?', opciones = '{"a": "Supresión de la fuente: que los diarios eliminen las notas originales de sus sitios, para que el contenido deje de existir.", "b": "Desindexación: que el buscador deje de vincular las notas con su nombre, aunque las publicaciones sigan disponibles en los diarios.", "c": "Rectificación: que se corrija la información publicada, porque en ambos casos las notas contienen datos inexactos o desactualizados.", "d": "Acceso: que el buscador les informe qué datos personales conserva sobre ellos y con qué criterio los ordena en sus resultados."}'::jsonb where id = 'etica-12-a';
update preguntas_clave set ok = 'b', porque = '{"a": "Se dirigen al buscador y no piden borrar las notas originales.", "c": "Las notas no son falsas: la veracidad no está discutida.", "d": "No piden conocer sus datos; piden que ciertos resultados no aparezcan."}'::jsonb where pregunta_id = 'etica-12-a';
update preguntas set texto = '¿A qué precedente se parece más el pedido de Ramiro y qué resultado sugiere?', opciones = '{"a": "A Denegri: el paso del tiempo por sí solo lleva a la Corte a ordenar la desindexación de la información antigua.", "b": "A Loomis: como el buscador ordena resultados con un algoritmo opaco, debe desindexar sin realizar ponderación alguna.", "c": "A BOSCO: Ramiro puede exigir que se revele cómo se ordenan los resultados y desindexar si el criterio no es explicable.", "d": "A Costeja: un particular sin proyección pública, con deuda superada y relevancia perdida con el tiempo, inclina a desindexar."}'::jsonb where id = 'etica-12-b';
update preguntas_clave set ok = 'd', porque = '{"a": "Denegri rechazó la desindexación; y la mera antigüedad no alcanza.", "b": "Loomis no trata el derecho al olvido.", "c": "BOSCO trata del acceso al código de la Administración, no de buscadores privados."}'::jsonb where pregunta_id = 'etica-12-b';
update preguntas set texto = '¿Qué debería primar en el pedido del exintendente, siguiendo el razonamiento de la CSJN?', opciones = '{"a": "La privacidad, porque tras más de diez años toda noticia pierde relevancia y el titular recupera su derecho a no ser vinculado.", "b": "La privacidad, porque el candidato es una persona como cualquier otra y su condición política no modifica la ponderación.", "c": "La libertad de expresión e información: se trata de información veraz sobre una figura pública y un tema de interés público actual.", "d": "Un equilibrio parcial: desindexar la mitad de las notas, así ambos derechos quedan protegidos en la misma medida."}'::jsonb where id = 'etica-12-c';
update preguntas_clave set ok = 'c', porque = '{"a": "Denegri: lo antiguo no es automáticamente irrelevante.", "b": "La proyección pública es justamente un factor central de la ponderación.", "d": "No es un criterio del material; la ponderación no es aritmética."}'::jsonb where pregunta_id = 'etica-12-c';
update preguntas set texto = 'Alguien dice: «Costeja y Denegri se contradicen, Europa olvida y Argentina recuerda». ¿Qué respondés?', opciones = '{"a": "Es incorrecto: ambos ponderan con el mismo método y llegan a resultados distintos porque las circunstancias son distintas.", "b": "Es correcto: el TJUE admite la desindexación y la CSJN la rechaza en cualquier circunstancia, por no reconocer el olvido.", "c": "Es correcto, y la diferencia se explica porque la ley argentina de datos personales es anterior al GDPR y no lo contempla.", "d": "Es incorrecto, porque en Denegri la Corte también ordenó desindexar los contenidos, igual que el TJUE en Costeja."}'::jsonb where id = 'etica-12-d';
update preguntas_clave set ok = 'a', porque = '{"b": "La CSJN dejó abierta la tutela excepcional ante contenido ilícito, daño concreto y vinculación lesiva.", "c": "La diferencia no se explica por la antigüedad de la ley sino por las circunstancias de cada caso.", "d": "En Denegri la CSJN revocó la desindexación."}'::jsonb where pregunta_id = 'etica-12-d';

commit;
